/**
 * Third content volume, authored as CSV.
 *
 * Kept separate from `content-volume.ts` so the two batches can be reviewed and
 * diffed independently, and so re-running the converter merges both rather than
 * replacing the first.
 *
 * Targets the thinner topics in the grid: CI/CD, IAM, Monitoring, Interview Prep
 * and Docker. Difficulty is deliberately mixed per file because the bank seeder
 * distributes questions round-robin across levels, so a single-difficulty batch
 * would skew the level split.
 *
 * Escaping rules, inherited from the existing blocks:
 *   - the options column is a JSON array wrapped in a CSV-quoted field
 *   - an inner quote is written as `""`
 *   - columns are: topic, text, options, correct, explanation, difficulty, tags
 */

export const BATCH_TWO: Record<string, string> = {};

BATCH_TWO["ci-cd"] = `topic,text,options,correct,explanation,difficulty,tags
ci-cd,"Why can a pipeline be green while the deployed artefact is broken?","[""Tests covered the branch, not the built image"", ""The runner cached a stale layer"", ""The pipeline skipped the deploy stage"", ""The health check was disabled""]",0,"A passing test suite says nothing about the image that will run. Build once, promote the same digest through every environment, and add a smoke test against the built artefact. Caching bugs and skipped stages are the other two common causes, and both should fail the build rather than pass silently.",MEDIUM,pipeline
ci-cd,"What is the safest way to handle a secret in a CI pipeline?","[""Store it in the CI platform's masked secret store and inject it at runtime"", ""Commit it to the repository and rotate later"", ""Pass it as a build argument, which is visible in image history"", ""Base64 encode it in the workflow file""]",0,"Secret stores mask the value in logs and keep it out of the repository. Build arguments end up in image history and are readable by anyone who can pull the image, so they are not a secret store. Base64 is encoding, not encryption.",EASY,secrets
ci-cd,"What does a blue/green deployment require that a rolling deployment does not?","[""Two identical production environments and a way to switch traffic between them"", ""A larger instance size"", ""A load balancer with sticky sessions"", ""Two database schemas""]",0,"Blue/green runs old and new simultaneously and switches the load balancer target, which needs both environments to exist. Rolling replaces instances in place, so it needs only one. Blue/green also makes rollback instant, which is why teams pick it despite the cost.",MEDIUM,deployment
ci-cd,"Why is database migration a common cause of failed deployments, and what mitigates it?","[""Schema changes can be incompatible with the currently running code, so use expand-and-contract"", ""Migrations are always reversible"", ""The database cannot be migrated during a deploy"", ""Migrations must run before every build""]",0,"Deploying a migration and the code that depends on it in the same step means one of the two is always mismatched. Expand-and-contract adds the new column first, ships code that writes both, backfills, then removes the old column in a later release.",HARD,deployment
ci-cd,"What is the difference between continuous integration and continuous delivery?","[""CI verifies every change builds and passes tests; CD also deploys it automatically"", ""CI is manual and CD is automated"", ""They are the same thing"", ""CD only applies to mobile apps""]",0,"CI is about verifying changes. Continuous delivery extends that to releasing automatically on every green build, usually behind a manual approval. Continuous deployment removes the approval step entirely.",EASY,concepts
ci-cd,"Which signal most reliably indicates a pipeline is flaky rather than genuinely broken?","[""The same commit passes on rerun with no code change"", ""The build takes longer than usual"", ""A test fails only on the first run every time"", ""The runner reports a timeout""]",0,"A commit that passes without any change is the definition of flakiness. This matters because retries mask real failures: a suite that fails 5% of the time hides a genuine regression in that 5%. Track flake rate as a metric and quarantine offenders.",MEDIUM,testing
ci-cd,"Why is caching dependencies worth the complexity in a container build?","[""Dependency layers change rarely, so cache hits make builds much faster"", ""It reduces the final image size"", ""It removes the need for a lock file"", ""It improves runtime performance""]",0,"Dependency resolution hits the network and rarely changes, so caching it means only your source layer is rebuilt. This has nothing to do with image size or runtime speed, both of which come from how you structure layers.",EASY,builds
ci-cd,"What is a monorepo's main CI problem?","[""One change triggers work across many packages, so affected-package detection is the hard part"", ""Monorepos cannot use containers"", ""Monorepos cannot run in parallel"", ""Monorepos have no dependency graph""]",0,"A change to a shared package should rebuild its dependents, not the whole repo. Tools such as Nx, Turborepo or Bazel compute that graph and run only affected jobs. The tradeoff is that without that tooling you pay full-build cost on every change.",HARD,monorepo
ci-cd,"When should a pipeline gate on a scan for hardcoded secrets?","[""Before merge, on every pull request"", ""Only before a release"", ""Only after a deployment"", ""Only when a secret is confirmed leaked""]",0,"Scanning on the pull request is the only point where the author can fix it before it reaches history. A later scan finds the secret in git history, where it must be treated as compromised and rotated regardless.",EASY,secrets
ci-cd,"What does a deployment gate based on error rate protect against?","[""Releasing a version that makes production worse"", ""Slow builds"", ""Flaky tests"", ""Expired credentials""]",0,"Automated gates compare production signals against the previous version and roll back when they degrade. This is the automated counterpart to canarying: catch a bad release in minutes rather than after a customer reports it.",MEDIUM,deployment
ci-cd,"Why is a pipeline that reuses the same runner without cleanup a security risk?","[""Credentials and workspace files persist on the runner between builds"", ""It cannot install dependencies"", ""It uses too much disk space"", ""It is slower to start""]",0,"Without isolation, a build can read files or credentials left by an earlier one, and a malicious build can persist on the runner for the next. Ephemeral runners, or a clean step that removes the workspace and injected secrets, close this off.",HARD,security
ci-cd,"What is the purpose of an artifact digest rather than a tag in a deployment?","[""It identifies the exact bits, so the same image is guaranteed everywhere"", ""It makes the image smaller"", ""It speeds up the pull"", ""It signs the image automatically""]",0,"Tags are mutable, so something can overwrite the tag between environments and you deploy different bytes than you tested. Digests are content-addressed and immutable, which is what makes build-once-promote-the-same-digest safe.",MEDIUM,deployment
ci-cd,"Which is a reasonable first step when a pipeline has become slow?","[""Measure where the time goes before optimising anything"", ""Increase the runner size immediately"", ""Split every stage in parallel"", ""Remove the test stage""]",0,"Most slow pipelines are dominated by one or two stages, often a cold dependency install or a serialised integration suite. Measuring first avoids paying for parallelisation that does not address the bottleneck.",EASY,concepts
ci-cd,"What does an ephemeral pull request environment help catch that unit tests miss?","[""Configuration and wiring errors, because the app runs as it would in production"", ""Syntax errors"", ""Type errors"", ""Documentation gaps""]",0,"Unit tests stub the outside world, so a missing environment variable, a wrong service name or a bad secret reference passes CI and fails on first boot. Booting the whole stack per pull request catches those.",MEDIUM,testing
ci-cd,"Why should build logs be treated as if they were public?","[""They are commonly readable by anyone with repository or CI access, and get pasted into issues"", ""They are encrypted"", ""They are deleted after a week"", ""They only contain hashes""]",0,"Logs routinely end up in chat threads, screenshots and bug reports. If a secret can be echoed by a failing command, assume it has already been exposed and rotate it rather than trying to recall where it was pasted.",EASY,secrets`;

BATCH_TWO["iam"] = `topic,text,options,correct,explanation,difficulty,tags
iam,"What is the difference between an explicit deny and no matching allow in an IAM policy?","[""An explicit deny always wins; no allow simply means no permission is granted"", ""They are equivalent"", ""An explicit deny only applies within the same statement"", ""No allow grants implicit read access""]",0,"Evaluation is deny-then-allow across the whole policy: any matching deny wins regardless of allows. Absence of an allow is equally final, so both mechanisms deny, but only one is intentional and visible in review.",EASY,policy
iam,"Why is granting wildcard permissions on wildcard resources a security problem even for a limited principal?","[""The principal can perform any action on any resource, and permissions are hard to revoke once used"", ""It only affects new resources"", ""Wildcards are slower to evaluate"", ""It is invalid syntax""]",0,"A principal with unrestricted permissions effectively owns the account, and access review tools treat a wildcard as too broad to reason about. Prefer the specific actions and resource ARNs the workload actually calls.",EASY,policy
iam,"What does an AWS IAM policy condition on aws:SourceVpce accomplish?","[""Allows the action only when the request arrives through the specified VPC endpoint"", ""Requires the request to come from a public IP"", ""Restricts the principal to one VPC"", ""Encrypts the request with the endpoint""]",0,"Endpoint policies and bucket policies together can require that traffic use a private path, which is how you block S3 exfiltration to the public internet while keeping the service reachable.",MEDIUM,policy
iam,"Why is it safer to pass an IAM role to an EC2 instance profile than to store access keys?","[""Credentials are fetched on demand and never written to disk, so they cannot be read from the instance"", ""Roles rotate more often"", ""Keys cannot be used with EC2"", ""Roles bypass the security group""]",0,"Instance profiles deliver short-lived credentials from the metadata service on demand. Static keys on an instance persist in its filesystem and get copied into images and snapshots, which is how they usually leak.",EASY,roles
iam,"What is the effect of an IAM role trust policy that allows a whole AWS account?","[""Any principal in that account that has sts:AssumeRole permission can assume it"", ""Every principal in the account gains the role automatically"", ""Only the root user can assume it"", ""The role becomes a managed policy""]",0,"The trust policy sets who may assume; the caller still needs its own permission. Naming an account is broad because every principal in it can be granted AssumeRole by anyone who can edit its policies, so prefer a specific role ARN.",MEDIUM,roles
iam,"Which statement about resource-based policies is correct?","[""A resource-based policy can grant access to principals outside the account"", ""Resource-based policies only restrict access"", ""They override an explicit deny in an identity policy"", ""They apply only to IAM users, not roles""]",0,"A bucket, KMS key or role trust policy is resource-based and can grant a cross-account principal access directly. They never override an explicit deny, which always wins.",MEDIUM,policy
iam,"What does the principle of least privilege mean for a CI/CD role?","[""Grant only the actions the pipeline actually performs, on the resources it names"", ""Grant all S3 actions but restrict to one region"", ""Grant the actions but add a condition on IP address"", ""Grant read-only everywhere and write to one bucket""]",0,"Least privilege is about the smallest set of actions on the smallest set of resources. Restricting by region or IP narrows the blast radius but leaves the role able to do far more than it needs within that scope.",EASY,policy
iam,"When should you use an IAM group rather than attaching policies to users directly?","[""When several people share a job function and the same permissions"", ""When a user needs more permissions"", ""When creating a service account"", ""When rotating keys""]",0,"Groups model job function and keep access consistent: add or remove the person, not the policy. Attaching to individuals means access drifts and you can no longer answer who has what by looking at one place.",EASY,policy
iam,"What does an SCP do that an IAM policy does not?","[""It sets the maximum permissions available to an account in an organisation, bounding what its IAM policies can grant"", ""It grants permissions to users"", ""It replaces the identity policies"", ""It applies only to root users""]",0,"SCPs are an allow-list ceiling applied at the account level. An identity policy can only ever narrow that ceiling, never widen it, which is what makes them useful for guardrails.",HARD,org
iam,"Why can a role trust policy cause an unexpected privilege escalation path?","[""If a low-privilege principal is allowed to assume a high-privilege role, it inherits that role's permissions"", ""Trust policies are evaluated after identity policies, so they add permissions"", ""A trust policy grants the role to every account"", ""Trust policies cannot be edited by account admins""]",0,"This is the classic confused-deputy pattern: a principal with AssumeRole on something powerful can effectively become that principal. Audit who can assume which roles, and use aws:ExternalId for third-party access.",HARD,roles
iam,"What is the practical effect of removing all inline policies but leaving managed policies attached?","[""The principal keeps the permissions from its managed policies"", ""The principal loses all permissions"", ""The account is locked out"", ""Only the console is affected""]",0,"Inline and managed policies are additive. Cleaning up inline policies while leaving managed ones attached is a common source of surprise access, so review both lists together.",EASY,policy
iam,"Why does using the AWS managed AdministratorAccess policy for a human user tend to be flagged in audits?","[""It cannot be scoped down and gives unrestricted access to every service including billing and IAM"", ""It expires after 90 days"", ""It is slower than a custom policy"", ""It is not available in all regions""]",0,"It is a valid choice for a break-glass account but a poor default: audits cannot distinguish real need from convenience, and it grants access to IAM and billing, the two things that make an account unrecoverable.",EASY,policy
iam,"What does sts:TagSession do during role assumption?","[""Passes session tags that appear in CloudTrail, letting you trace who assumed the role"", ""Encrypts the session token"", ""Extends the session duration automatically"", ""Requires MFA""]",0,"Session tags are the cleanest way to attribute an assumed role back to a person in an audit trail, especially when the principal itself is just a role.",MEDIUM,roles
iam,"Which is a real risk of using a single long-lived IAM user for automation?","[""The key can leak and there is no automatic rotation, and it cannot be tied to a session"", ""It cannot be used with the CLI"", ""It is limited to one region"", ""It is deleted after 30 days""]",0,"Long-lived keys are a standing liability: anyone who obtains one has that access until someone notices. IAM roles with short-lived credentials remove both the rotation problem and the attribution problem.",EASY,roles`;

BATCH_TWO["monitoring"] = `topic,text,options,correct,explanation,difficulty,tags
monitoring,"What are the four golden signals?","[""Latency, traffic, errors, saturation"", ""CPU, memory, disk, network"", ""Uptime, availability, latency, throughput"", ""Errors, logs, metrics, traces""]",0,"Latency tells you how long users wait, traffic tells you the demand, errors tell you what is broken, and saturation tells you how close you are to the limit. The other lists describe either causes or channels rather than the user-facing view.",EASY,concepts
monitoring,"Why is a percentile better than an average when measuring request latency?","[""Averages hide the slow tail that real users actually experience"", ""Percentiles are cheaper to compute"", ""Averages require more samples"", ""Percentiles cannot be aggregated across services""]",0,"If 1% of requests take 30 seconds, the average barely moves but a meaningful number of users had a bad time. p50, p95 and p99 describe the experience; the average does not.",EASY,metrics
monitoring,"What does a high p99 with a normal p50 usually indicate?","[""A small number of very slow requests, often GC pauses, lock contention or a slow dependency"", ""The service is uniformly slow"", ""The metrics pipeline is broken"", ""The traffic is evenly distributed""]",0,"The gap between median and tail is the signature of intermittent problems: garbage collection pauses, connection pool exhaustion or a downstream call occasionally hanging. Uniform slowness shows up in p50 too.",MEDIUM,metrics
monitoring,"When should an alert fire on a symptom rather than a cause?","[""When the symptom is user-visible and you want fewer, more actionable pages"", ""Never"", ""Always, because causes are more specific"", ""Only in development environments""]",0,"Alerting on CPU causes pages nobody can act on. Alerting on error rate and latency pages the team that can fix it. Causes belong on a dashboard for diagnosis, not in the paging path.",MEDIUM,alerting
monitoring,"What makes an alert actionable that a dashboard notification is not?","[""It has a runbook link, a clear owner, and fires on something a human must act on now"", ""It includes a graph"", ""It fires more often"", ""It is sent by email""]",0,"An alert is an interruption. That cost is only justified if there is a named owner, a documented response, and a reason to act immediately. Everything else belongs on a dashboard people check.",EASY,alerting
monitoring,"What does cardinality mean for a metric label?","[""The number of distinct values a label takes, which multiplies storage and query cost"", ""The precision of a measurement"", ""The sampling rate"", ""The time range of a query""]",0,"Labelling every metric with a user ID creates millions of time series from one metric, which is a common and expensive self-inflicted outage. Keep labels to bounded values like status code or endpoint.",MEDIUM,metrics
monitoring,"Why is a scrape-based monitoring system a poor fit for very short-lived containers?","[""The container may exit before it is ever scraped"", ""Scraping requires root access"", ""Scrape targets cannot use DNS"", ""It only works with virtual machines""]",0,"A pod that lives 200 milliseconds may never exist at a scrape instant. For that, push metrics from a sidecar or agent, or use the orchestrator's own event stream.",MEDIUM,metrics
monitoring,"What is the main operational risk of relying solely on a shallow metrics-based health check?","[""A service can serve errors quickly and still be reported healthy"", ""Metrics are always delayed"", ""Health checks cannot be automated"", ""Metrics require a paid tier""]",0,"Liveness checks that only verify the process responds will happily keep a service in rotation while it returns 500s. Readiness and startup probes should check what the service actually depends on.",MEDIUM,alerting
monitoring,"What does a distributed trace give you that metrics and logs do not?","[""The causal path across services for a single request, with per-span timing"", ""Cheaper storage"", ""A count of errors per endpoint"", ""A single dashboard for all services""]",0,"Metrics tell you something is slow; traces tell you which hop is responsible. Sampling keeps the volume manageable while preserving the ability to inspect an individual slow request.",MEDIUM,tracing
monitoring,"What is the purpose of log levels, and what is a common misuse?","[""They filter noise; the misuse is leaving debug enabled in production, which floods storage and hides real errors"", ""They improve performance"", ""They are used for authentication"", ""They replace metrics""]",0,"Levels exist so operators can raise or lower verbosity without a deploy. Leaving debug on in production is the standard failure: it fills the pipeline, raises cost, and pushes important lines out of retention.",EASY,logging
monitoring,"How should you measure an SLO rather than a metric?","[""As the proportion of good events to valid events over a window, with an error budget derived from it"", ""As an absolute threshold on one service"", ""As the average response time"", ""As the number of alerts per week""]",0,"An SLO is a user-facing reliability target over a period. The error budget that falls out of it is what tells you whether you can ship a risky change this week or must spend the week on stability.",MEDIUM,slo
monitoring,"What causes alert fatigue and how is it best prevented?","[""Too many low-value alerts; fix it by requiring an owner and a runbook, and deleting alerts nobody acts on"", ""Alerts sent too slowly"", ""Using too many metrics"", ""Not having a dashboard""]",0,"People stop reading alerts when most are noise, and then miss the real one. Auditing which alerts have ever produced a response is the fastest way to cut the volume.",EASY,alerting
monitoring,"What does a histogram bucket boundary change affect?","[""The accuracy of percentile estimates for values in that range"", ""The ingestion cost only"", ""Nothing, buckets are cosmetic"", ""The metric's timestamp""]",0,"Latency is a distribution, and percentiles are computed from buckets. Moving boundaries around the region you care about, typically the slow tail, changes how precisely p99 can be estimated there.",MEDIUM,metrics
monitoring,"Why should a service expose separate liveness and readiness probes?","[""Liveness answers should it be restarted; readiness answers should it receive traffic. Conflating them causes restart storms"", ""It halves the number of probes"", ""Readiness probes are required by Kubernetes"", ""It improves latency""]",0,"If readiness returns failure whenever a dependency blips, every instance leaves the load balancer at once and the outage spreads. Liveness should stay shallow so a slow dependency does not trigger a restart loop.",MEDIUM,alerting
monitoring,"What is the main drawback of using host-level CPU as a scaling signal?","[""CPU is a poor proxy for demand and can lag or mislead under IO-bound work"", ""CPU is too expensive to collect"", ""It cannot be collected per pod"", ""It only works in the cloud""]",0,"IO-bound services often sit at low CPU while queue depth climbs, so autoscaling on CPU under-provisions them. Queue length or request concurrency tracks demand more directly for those workloads.",MEDIUM,metrics`;

BATCH_TWO["interview-prep"] = `topic,text,options,correct,explanation,difficulty,tags
interview-prep,"You are asked to explain a production outage you did not cause. What is the strongest opening?","[""State what you observed, what you ruled out, and what you changed, with the evidence"", ""Apologise and move on quickly"", ""Describe how the previous team should have prevented it"", ""Give your opinion on the architecture first""]",0,"Interviewers are testing how you reason under pressure. Leading with observations, eliminations and evidence demonstrates the process; leading with blame or architecture opinion does not, whatever the merits.",MEDIUM,communication
interview-prep,"What is the difference between explaining a tool and explaining a decision?","[""A decision includes the constraints and alternatives considered; a tool description does not"", ""There is no difference"", ""Decisions are shorter to explain"", ""Tools are easier to discuss""]",0,"Interviewers have heard the tool description many times. What distinguishes a strong candidate is naming the constraint that forced the choice, the alternatives rejected, and the trade-off accepted. That is the part they cannot get from documentation.",MEDIUM,communication
interview-prep,"When you do not know the answer to a technical question, what is the best response?","[""Say what you do not know, describe how you would find out, and answer the part you are confident about"", ""Guess confidently, because admitting gaps looks weak"", ""Change the subject to something you know"", ""Say you would ask a colleague rather than answering""]",0,"Interviewers are assessing reasoning, not recall. Naming the exact command, log or document you would check demonstrates that you know how to find answers, which is the actual job requirement.",EASY,communication
interview-prep,"How should you answer a question about a weakness or a gap in your experience?","[""Name a real gap, show what you are doing to close it, and give an example of learning quickly"", ""Pick a weakness that sounds like a strength"", ""Say you have no gaps"", ""Deflect to a strength""]",0,"A gap with a plan and evidence of self-teaching is credible. A disguised strength reads as evasive, and claiming none is usually challenged by the first technical question.",EASY,communication
interview-prep,"In a system design question, when should you start discussing trade-offs?","[""After clarifying requirements and scale, before proposing technology"", ""After choosing the stack"", ""Only if the interviewer asks"", ""At the end, as a summary""]",0,"Trade-offs before requirements are meaningless because you do not know what matters yet. Once read and write throughput or consistency needs are stated, the constraints become concrete and trade-offs can be discussed meaningfully.",MEDIUM,design
interview-prep,"What is the most useful thing to do when a system design interview goes off script?","[""State the assumption you are making and ask whether it matches what they had in mind"", ""Follow the question silently and hope it works out"", ""Ask to start over"", ""Answer with a generic architecture diagram""]",0,"Interviews are often deliberately open-ended. Verbalising an assumption lets the interviewer correct it early, which is exactly the communication skill the interview is testing.",EASY,design
interview-prep,"How should you describe the impact of a project quantitatively when you lack formal metrics?","[""Give a before-and-after comparison with the measurement method you used, and be explicit about its limits"", ""Estimate a percentage confidently"", ""Describe the effort rather than the result"", ""Say the metrics were not available""]",0,"Interviewers can tell the difference between a precise number and a bounded estimate. Stating the method and its limits is more credible than a confident figure, and it demonstrates measurement discipline.",MEDIUM,communication
interview-prep,"What should you ask at the end of an interview?","[""How the team decides success in the role, and what a recent failure taught"", ""When the next interview is"", ""Whether the office has parking"", ""What the salary band is""]",0,"Asking how success is measured tells you what the role actually is, which is often more informative than the job description. Questions about specific recent failures usually produce candid, revealing answers.",MEDIUM,communication
interview-prep,"Why is describing what you personally did, rather than what the team did, important?","[""Interviews assess individual capability, and vague team framing reads as evasion"", ""It is more polite"", ""It makes the answer shorter"", ""It avoids follow-up questions""]",0,"Use we for context but be precise about your own contribution. An interviewer who cannot separate your contribution may assume the weakest part of it was yours.",EASY,communication
interview-prep,"What is a reasonable way to handle a disagreement with a senior engineer in a technical discussion?","[""Present the concern with evidence, commit to their decision if it is made, and offer to test your hypothesis"", ""Argue until you win"", ""Defer immediately without comment"", ""Escalate to your manager""]",0,"This is the classic probe for whether someone can raise a concern without being obstructive. Committing to the decision once made, and offering a cheap way to verify, is what separates a professional from an obstacle.",MEDIUM,behaviour
interview-prep,"How much implementation detail should you give when asked to whiteboard a pipeline?","[""Enough to show the stages, their inputs and outputs, and the failure handling"", ""Every line of the config file"", ""Only the diagram, no detail"", ""Only the code, no diagram""]",0,"Interviewers are looking for whether you know what each stage needs and how failures flow. Reading out configuration line by line burns the time that should go to reasoning.",EASY,design
interview-prep,"What is the best way to prepare for a behavioural question about a difficult decision?","[""Prepare the situation, your options, what you chose, what you would change, and the measured outcome"", ""Memorise a polished script"", ""Prepare only a success story"", ""Rehearse broad generalities""]",0,"Interviewers follow up on the decision and the reflection, not the narrative. Having the options and the retrospective ready is what makes the answer sound considered rather than rehearsed.",EASY,behaviour`;

BATCH_TWO["docker"] = `topic,text,options,correct,explanation,difficulty,tags
docker,"What is the practical effect of copying the whole context as the last line of a Dockerfile?","[""Any source change invalidates that layer and every step after it, so builds stay slow"", ""It makes the image smaller"", ""It excludes the build context"", ""It enables layer caching""]",0,"Layer caching keys on the files a step touches. Copying the whole context last means every code change busts that layer, so dependency installation gets re-run. Copy the manifest first, install, then copy the source.",MEDIUM,builds
docker,"Why should a container run as a non-root user?","[""It limits the impact of a container escape or a compromised process inside it"", ""It speeds up the container"", ""It reduces image size"", ""It is required by Docker""]",0,"A process running as root inside a container can do more damage if it is ever broken out of, and it removes one of the easiest escalation paths. It is a cheap layer of defence, not a complete one.",MEDIUM,security
docker,"What is the difference between COPY and ADD in a Dockerfile?","[""ADD can extract local tar archives and fetch from URLs; COPY does neither"", ""COPY is deprecated"", ""ADD is faster"", ""They are identical""]",0,"COPY is the predictable choice. ADD's extra behaviours make builds harder to reason about and, when it fetches a URL, mean the image contents depend on network state at build time.",EASY,builds
docker,"Why does a multi-stage build reduce final image size?","[""Build tools and intermediate artefacts stay in the discarded stage"", ""It compresses the layers"", ""It removes unused files automatically"", ""It runs the build in parallel""]",0,"Compilers, package headers and build caches can dwarf a runtime image. Building in one stage and copying only the artefacts into a clean runtime stage leaves all of that behind.",EASY,builds
docker,"What does a .dockerignore file prevent?","[""Local files being sent to the daemon as build context, which speeds builds and keeps secrets out of the image"", ""The image from being pushed to a registry"", ""The container from starting"", ""Docker Compose from starting""]",0,"Without it, node_modules, .git and any local .env file are all uploaded as context on every build. That is the most common way secrets end up in images.",EASY,builds
docker,"What is the risk of running a container with the host network mode?","[""The container shares the host's network namespace, so an exposed port is exposed on the host"", ""It cannot reach the internet"", ""It disables DNS"", ""It requires root""]",0,"Host networking removes network isolation entirely: a container listening on 8080 is listening on the host's 8080. It is occasionally justified for high-performance or local-development cases, but it should be a deliberate exception.",MEDIUM,security
docker,"How does a Docker healthcheck differ from a Kubernetes readiness probe?","[""Docker marks a container unhealthy; it does not remove it from traffic or restart it by default"", ""They are identical"", ""Docker restarts unhealthy containers automatically"", ""Kubernetes ignores healthcheck""]",0,"A failed Docker HEALTHCHECK only changes the reported status. Orchestrators are what act on it: Compose honours it for depends_on conditions, and Kubernetes maps it to readiness.",MEDIUM,operations
docker,"What problem does a volume solve that a bind mount does not?","[""Volumes are managed by Docker and survive image rebuilds and container replacement"", ""Volumes are faster"", ""Volumes are read-only"", ""Bind mounts are deprecated""]",0,"A bind mount points at a host path and inherits its permissions and ownership. A named volume is created and owned by Docker, which is why it is the right default for databases and anything with state that must survive redeploys.",EASY,storage
docker,"What is the safest base image choice for a production container?","[""A pinned minimal image, such as a distroless or alpine variant, by digest"", ""latest, for automatic security updates"", ""A full distribution image, for compatibility"", ""The image with the most stars""]",0,"latest is unreproducible, which is the larger risk. Pin a digest so you know exactly what runs, and rebuild deliberately when you choose to pick up patches. Minimal images also shrink your attack surface.",MEDIUM,builds
docker,"Why can a container using a bridge network still reach the internet while appearing isolated?","[""NAT translates its outbound traffic through the host, so inbound is blocked but outbound is allowed by default"", ""Bridges are not isolated"", ""It requires host networking"", ""The image resolves DNS externally""]",0,"Default bridge networking gives outbound access via masquerading while blocking unsolicited inbound. That asymmetry surprises people: an exposed published port is inbound, and it is what opens the container up.",MEDIUM,networking
docker,"What does a container's writable layer mean for logs and state?","[""Anything written there is lost when the container is removed"", ""It is encrypted at rest"", ""It is shared with the host"", ""It is backed up automatically""]",0,"The writable layer is ephemeral by design, which is good for immutability but means logs and state must go to a volume or an external sink or they vanish on redeploy.",EASY,storage
docker,"What is the practical downside of running everything as one container to keep deployment simple?","[""A failure or a scale requirement in one component forces the others to move with it"", ""It uses more memory"", ""It cannot be orchestrated"", ""It prevents CI""]",0,"One process per container is a constraint that pays off later: independent scaling, independent restarts and clearer failure domains. Splitting by concern is not extra complexity, it is deferred complexity avoided.",MEDIUM,design
docker,"How does an image layer differ from a file in the final image?","[""Each instruction creates a layer; files added earlier are still there even if deleted later, which grows the image"", ""Layers are compressed copies of the filesystem"", ""A layer is a running process"", ""Layers are created at runtime""]",0,"Because layers are additive, deleting a file in a later step only hides it in that layer; the bytes remain in the layer below. This is why removing and reinstalling a package in a later step makes an image bigger rather than smaller.",HARD,builds
docker,"What is the purpose of a container healthcheck versus a liveness probe, in plain terms?","[""Healthcheck reports status to Docker; liveness decides whether to kill and restart the container"", "They do the same thing", "Healthcheck restarts the container", "Liveness only reports status"]",0,"Keeping them separate prevents a slow dependency from causing a restart storm: the container can stay alive while being pulled out of rotation.",EASY,operations
docker,"Why can a container running as root be a problem even when it never breaks out?","[""A compromised process inside has more capability than it needs, increasing the damage of any escape"", "It cannot bind to low-numbered ports", "It uses more CPU", "It cannot read environment variables"]",0,"Least privilege inside the container matters for the same reason it does on a host. A read-only filesystem and a dropped capability set narrow this further.",EASY,security
docker,"When is a bind mount preferable to a volume in production?","[""Rarely; volumes are preferred because Docker manages ownership and persistence"", ""When the host path must be shared with other tools"", ""For read-only configuration only"", ""Never, in any case""]",0,"Bind mounts make the container's behaviour depend on host state and permissions, which is exactly the coupling you want to avoid in production. They remain common in local development for live reload.",MEDIUM,storage
docker,"How do you keep a container's filesystem from being modified at runtime?","[""Run with the read-only root filesystem flag and mount writable volumes only where needed"", "Run as root", "Disable the healthcheck", "Use host networking""]",0,"A read-only root filesystem removes a whole class of persistence-based attacks and forces the application to write only to mounted paths, which is where its data should live anyway.",MEDIUM,security
docker,"Which statement about container resource limits is accurate?","[""A limit protects the host by capping what one container can consume"", "Limits make the container faster", "Limits are advisory and ignored by the kernel", "Limits apply to images rather than containers"]",0,"Without a memory limit a single process can exhaust host memory and take the node down. Limits are the mechanism that makes one workload's mistake not become everyone's outage.",EASY,operations
docker,"Why does an image tagged latest carry extra risk in a CI pipeline?","[""It is mutable, so two builds can resolve to different bytes"", "It cannot be pulled by digest", "Registries do not support it", "It is always the largest image"]",0,"Unreproducible builds make both verification and rollback unreliable. Pin a digest in deployment and keep the tag only as a convenience alias.",EASY,builds
docker,"What is a common cause of a container exiting immediately after start?","[""The entrypoint command finished, because a container stops when PID 1 exits"", "The image is too large", "The healthcheck is too aggressive", "The volume is read-only"]",0,"A container's lifecycle is tied to its main process. If that process runs and exits, the container stops. Foregrounding the server, rather than starting it and exiting, is the usual fix.",MEDIUM,operations
docker,"How does a multi-stage build avoid shipping build credentials?","[""The stage that needs the credentials is discarded; only the copied artefacts survive"", "Docker encrypts them automatically", "The credentials are never written to disk", "The registry removes them"]",0,"Build secrets do not need to be in the final image at all if the artefacts are produced in a separate stage and only copied forward. This is the practical defence against credentials leaking into production images.",MEDIUM,security
docker,"What does CPU quota limiting do differently from CPU shares?","[""A quota caps total CPU time per period, so a container is throttled once it exceeds it; shares only weight contention"", "They are the same setting", "Shares cap memory", "Quota only applies to GPU workloads"]",0,"Shares distribute CPU when there is contention, which does nothing on an idle host. A quota enforces a ceiling regardless, which is what you want to guarantee headroom for neighbours.",HARD,operations
docker,"What is the practical consequence of putting a database and an application in one container?","[""They cannot be scaled, upgraded or restarted independently"", "The image becomes too large", "They cannot share a volume", "The database stops working"]",0,"Independent scaling is the main loss: a busy application cannot scale out without also scaling the database, which is usually not what you want and often not possible.",MEDIUM,design
docker,"Why can an image become unexpectedly large even after deleting a large file?","[""Deletion happens in a later layer but the bytes remain in the earlier one"", "The build cache is not pruned", "The base image is too large", "Docker compresses deleted files"]",0,"Layers are immutable and additive. Squashing with a multi-stage build is the fix, because the intermediate layer never reaches the final image.",MEDIUM,builds
docker,"What should a container's healthcheck actually verify?","[""That the service can serve its core function, not just that the process is alive"", "That the process exists", "That the port is bound", "That the image is present"]",0,"Process and port checks pass happily while a service returns errors to every caller. Checking the core function is what turns a healthcheck into a real signal, though it does add load, so keep it cheap and infrequent.",MEDIUM,operations
docker,"Which is a valid reason to use a bind mount in production?","[""Rarely; mounting a host socket such as the Docker socket is dangerous, not a legitimate shortcut"", "It is faster than a volume", "It is required for stateful services", "It survives container replacement"]",0,"Volumes are the right choice for production state. Bind mounts over host sockets, particularly the Docker socket, effectively grant root-equivalent control of the host and are a serious escalation path.",MEDIUM,security
docker,"What happens to a container's exit code and how does it affect restarts?","[""It tells the orchestrator whether the process succeeded; the restart policy decides whether to retry"", "It is logged and otherwise ignored", "It resets the container's health status", "It determines the image tag"]",0,"Exit codes are the primary signal for whether a process failed, and restart policies such as always-on-failure act on them. This is why a service that exits cleanly on crash is so hard to diagnose.",EASY,operations
docker,"Why is it risky to pass build arguments containing secrets into a Docker build?","[""They persist in image history and can be recovered from the image"", "They are encrypted in transit", "They are ignored by the daemon", "They expire when the build finishes"]",0,"Build args are recorded in the image metadata, so anyone who can pull the image can read them. Use BuildKit's secret mounts, which mount the value only for the build step and leave nothing behind.",MEDIUM,secrets
docker,"How should you decide what goes into a container image?","[""The runtime and its direct dependencies only, nothing needed to build them"", "Everything the build needs", "The host filesystem minus mounts", "Only the application source"]",0,"Carrying build tools into the runtime image multiplies its size and its CVEs. A multi-stage build keeps the build toolchain in a stage that is discarded, leaving only what runs.",EASY,builds
docker,"What is the risk of running a container with all capabilities dropped except the ones required?","[""Little; it is a recommended hardening step that removes escalation paths"", "The container cannot start", "It requires Kubernetes", "It prevents logging"]",0,"Docker's default capability set is broader than most applications need. Dropping to a minimal set removes known privilege escalation routes such as mounting filesystems.",MEDIUM,security
docker,"When is a sidecar container a reasonable pattern?","[""When a capability, such as a proxy or a log shipper, must be tightly coupled to a workload's lifecycle"", "Whenever a service has any dependency", "To avoid writing any code", "For any stateless workload"]",0,"A sidecar shares the pod's network and lifecycle, which is genuinely convenient, but it also couples scaling and resource use to the main container. Separate deployment is often the better default.",MEDIUM,design
docker,"What does restarting on a failed healthcheck risk?","[""Restart loops that hide the underlying failure and lose in-flight work"", "Nothing, it is always correct", "Faster traffic recovery", "Lower memory use"]",0,"Automatic restarts are appropriate for a process that failed to start, not for one that is running but unhealthy, where the problem is usually a dependency. Distinguishing the two avoids masking outages.",MEDIUM,operations
docker,"Which is true of Docker's default logging driver?","[""It writes JSON to a local file that is not rotated by default"", "It ships to a central collector automatically", "It discards logs when a container exits", "It compresses log output"]",0,"Without rotation, a chatty container fills the disk. Configure a log driver with size and count limits, or use the platform's log collector, before you hit production.",MEDIUM,operations
docker,"How does a container image tag differ from a digest in terms of reproducibility?","[""A tag can be moved to a new image; a digest is content-addressed and immutable"", "They are identical", "A digest cannot be pulled", "Tags are always reproducible"]",0,"Reproducibility comes entirely from the digest. Tags are human-readable aliases that can point anywhere at any time, which is why deployment manifests should reference digests and lock files pin them.",EASY,operations
docker,"What is the practical benefit of a distroless base image?","[""It removes the shell and package manager, shrinking the attack surface"", "It speeds up builds", "It makes debugging easier", "It enables multi-stage builds"]",0,"Removing the shell closes a large set of known exploitation paths. The tradeoff is real, though: you cannot exec into a running container to debug it, so pair it with strong logging.",MEDIUM,security
docker,"How should you structure a Dockerfile for cache efficiency?","[""Copy the dependency manifest and lock file, install, then copy application source"", "Copy everything, then install", "Install after every COPY step", "Use a single stage with all commands"]",0,"Ordering by change frequency is the whole idea: manifests change rarely, source changes constantly. Putting source last means routine edits reuse the dependency layer.",MEDIUM,builds
docker,"What does an init process in a container help with?","[""Reaping zombie processes and forwarding signals, so PID 1 behaves correctly"", "Speeding up startup", "Encrypting the filesystem", "Setting resource limits"]",0,"Zombie reaping and signal forwarding are the two things apps get wrong as PID 1. An init process, or an exec-form entrypoint, avoids both classes of bug.",MEDIUM,operations
docker,"What is the effect of marking a Dockerfile instruction as a cache mount?","[""The step's side effects are cached for the build but excluded from the image"", "The image becomes smaller", "The build cannot use the registry cache", "The instruction is skipped"]",0,"This is how BuildKit keeps package manager indexes and caches out of the image while still making rebuilds fast, addressing two problems with one mechanism.",MEDIUM,builds
docker,"Why does a container sometimes need a higher file descriptor limit than the default?","[""Each connection consumes a file descriptor, and the default ulimit can be exhausted under load"", "It reserves more CPU", "It changes the image size", "It improves DNS resolution"]",0,"A service handling a few thousand concurrent connections can hit the default descriptor limit, producing confusing accept failures. Raising the limit, or proxying through something that multiplexes connections, fixes it.",MEDIUM,operations
docker,"What is a common cause of an image build succeeding but the container failing at runtime?","[""The image targets a different libc or architecture than the host, or an arch-specific native dependency is missing"", "The image tag was wrong", "The Dockerfile had a typo", "The healthcheck was omitted"]",0,"Multi-architecture builds and native modules are the usual culprits. Building for arm64 and running on amd64, or the reverse, produces exactly this symptom.",MEDIUM,builds
docker,"Why should an application in a container bind to all interfaces rather than loopback?","[""Binding to loopback makes the service unreachable from outside the container"", "It uses less memory", "It is required by Docker", "It improves security"]",0,"Loopback inside a container is the container's own loopback, not the host's, so published ports appear dead. This is one of the most common first-run failures.",EASY,networking
docker,"What is the purpose of a scratch base image in a Dockerfile?","[""To start from nothing, so only files you explicitly copy exist in the final image"", "To speed up builds", "To add a shell for debugging", "To enable shell commands"]",0,"Scratch is the most minimal base available. It has no shell, no package manager and no utilities, which maximises security and minimises size at the cost of debuggability.",EASY,builds
docker,"How should a long-running service handle configuration that differs per environment?","[""Inject it at runtime as environment variables or mounted files, not baked into the image"", "Rebuild the image per environment", "Hardcode it in the Dockerfile", "Store it in a layer label"]",0,"One image promoted through environments is the point of the pattern. Baking configuration in forces a rebuild per environment and defeats build-once-promote-the-same-digest.",MEDIUM,deployment
docker,"What is the difference between an image and a container?","[""An image is a filesystem and metadata; a container is a running instance of it"", "There is no difference", "A container is smaller than an image", "A container includes the kernel"]",0,"Containers do not include a kernel. The distinction matters for understanding that many containers share one host kernel, which is also where the isolation boundaries sit.",EASY,concepts
docker,"Why is it a problem to run a database in a container without a persistent volume?","[""Data is written to the container's writable layer and lost when the container is replaced"", "The database will not start", "It uses too much memory", "The volume is required for networking"]",0,"This is the classic stateful-service footgun. The data lives in the writable layer, so a redeploy that recreates the container silently discards it.",EASY,storage
docker,"What is a reasonable strategy for storing secrets in a container at runtime?","[""Mount them from a secret manager as files, and rotate without rebuilding the image"", "Bake them into the image with a build argument", "Store them in a compose file committed to the repo", "Base64 them in an environment variable"]",0,"Runtime injection from a secret manager keeps credentials out of the image and the repository, and lets you rotate without a redeploy. The others each leak in a different, well-documented way.",MEDIUM,security
docker,"What does an image manifest list enable?","[""One tag resolving to the correct image for the host's architecture"", "Layer compression", "Faster pulls on the same architecture", "Signing multiple images"]",0,"This is what lets one tag work across amd64 and arm64 without anyone tracking which is which. Pin the digest when you need a specific build rather than a specific platform.",MEDIUM,operations
docker,"When does a container need a PID namespace of its own?","[""Almost always in production; sharing the host PID namespace exposes every host process to the container"", "Only for containers running systemd", "Never, it is the default and cannot be changed", "Only on bare metal"]",0,"Default PID isolation is one of the meaningful boundaries between containers. Disabling it for debugging is fine; disabling it in production is not.",MEDIUM,security
docker,"What is the effect of a container exceeding its memory limit?","[""The OOM killer terminates it, which appears as an abrupt exit with no application error"", "It is throttled and slows down", "It is automatically restarted by Docker", "It swaps to disk"]",0,"An OOM kill looks like a mystery exit, which is why it is worth watching for. Raising the limit treats the symptom; the fix is usually a leak or an unbounded cache.",MEDIUM,operations
docker,"Why is installing packages in a single run instruction an optimisation?","[""Each instruction creates a layer, so separate install and cleanup steps leave the package files behind and bloat the image"", "It makes the install faster", "It improves security", "It enables caching"]",0,"Removing the package lists in a later step leaves the earlier copy in place. Combining install and cleanup in one instruction, or using multi-stage builds, keeps those bytes out.",EASY,builds
docker,"What is the risk of using a wildcard in a Dockerfile copy source path?","[""The context sent to the daemon grows with everything in it, slowing builds and risking secrets in the image"", "Docker rejects the build", "It copies only matching files safely", "It enables layer caching"]",0,"The wildcard is expanded client-side against the build context, so the whole context still gets uploaded. A .dockerignore is the actual control here.",MEDIUM,builds
docker,"What does a container's OCI specification standardise?","[""The image format and runtime configuration, so images are portable between runtimes"", "Only the networking driver", "Only the volume format", "The build cache behaviour"]",0,"Being able to move an image between runtimes without rebuilding depends entirely on this standard, which is what prevents vendor lock-in at the image level.",EASY,concepts
docker,"How should you expose a container port to the host?","[""Publish it explicitly, and restrict the binding to a specific host interface"", "The EXPOSE instruction, which publishes it automatically", "Both; EXPOSE alone is sufficient", "Set it in the compose file without a publish flag"]",0,"EXPOSE is documentation only; it does not publish anything. Binding the host side to loopback avoids exposing a service to the network by accident.",EASY,networking
docker,"What is the practical reason to prefer immutable containers over ones you mutate at runtime?","[""A mutated container cannot be reproduced from its image, so the running state is untraceable"", "Immutable containers run faster", "Mutable containers cannot be orchestrated", "Immutable containers use less memory"]",0,"Reproducibility is the whole argument. If the running system is described by an image and configuration rather than by a sequence of manual changes, you can rebuild it exactly.",MEDIUM,operations
docker,"What does passing a no-new-privileges flag do when running a container?","[""Prevents processes from gaining extra privileges through setuid or setgid binaries"", "Disables privilege escalation entirely", "Removes the root user", "Prevents network access"]",0,"It is a cheap, effective hardening flag that blocks a common escalation technique without affecting normal application behaviour.",MEDIUM,security
docker,"When is it correct to choose a sidecar proxy over handling concerns in the application?","[""When cross-cutting concerns like TLS termination or request logging should be consistent and independent of application deploys"", "Whenever possible, to keep applications simple", "Only in development", "Never, sidecars add latency"]",0,"Sidecars suit uniform cross-cutting concerns where independent iteration is a benefit. They are a poor fit when the logic is genuinely business-specific and needs to change with the application.",MEDIUM,design
docker,"What is the practical consequence of logging to stdout with no log rotation?","[""The JSON log file grows until it fills the disk and affects the host"", "Logging is disabled automatically", "Only stdout is affected and is bounded", "The container cannot write logs"]",0,"Because the default JSON log driver does not rotate, a chatty service eventually consumes the node's disk. Setting size and count limits is a small change that prevents a large outage.",EASY,operations
docker,"What distinguishes a container from a virtual machine in terms of isolation?","[""Containers share the host kernel and isolate with namespaces and cgroups; VMs virtualise the hardware and run their own kernel"", "Containers provide stronger isolation", "Both run their own kernel", "They are identical"]",0,"Containers are lighter because they share the kernel, and weaker because that kernel is a shared failure domain. That is the tradeoff, not a defect.",EASY,concepts
docker,"Why does an image pushed to a registry need a digest recorded alongside its tag?","[""The tag can move, so the digest is what identifies the exact bytes that were tested and deployed"", "Digests are faster to pull", "Registries require both", "It enables encryption"]",0,"Recording the digest is what lets you prove later that the deployed image is the one that passed testing, and makes rollback precise.",MEDIUM,deployment
docker,"What is the danger of running a container with the Docker socket mounted?","[""Anyone who compromises the container can effectively control the host daemon, which is equivalent to root"", "The container cannot start", "It prevents volume mounts", "It uses more memory"]",0,"The socket is the host's control plane. Mounting it into a container hands over the ability to start privileged containers on the host, which is why it appears in so many container-escape writeups.",MEDIUM,security
docker,"How does an image layer cache key get computed?","[""From the instruction and the checksums of the files it consumes"", "From the build timestamp", "From the image tag", "From the container name"]",0,"Because the key includes input file checksums, changing a file invalidates only the layers that consume it and everything after. That is the entire basis for optimising layer ordering.",MEDIUM,builds
docker,"What is a practical reason to run a registry mirror or pull-through cache?","[""It reduces repeated pulls of the same large base images and works around rate limits"", "It improves image security automatically", "It signs images", "It compresses layers"]",0,"Public registry pull limits affect CI reliability. A mirror in the same region or a local pull-through cache removes both the latency and the throttling risk.",MEDIUM,operations
docker,"What should you check first when a container starts but immediately becomes unhealthy?","[""Its logs, then the probe endpoint itself, since a wrong path or port reports unhealthy regardless of app health"", "The image tag", "The registry credentials", "The container's memory limit"]",0,"Probe misconfiguration is the most common cause: an off-by-one port or a path behind an auth check makes a perfectly healthy service report unhealthy forever.",EASY,operations
docker,"Why does running as a non-root user inside a container interact with file ownership?","[""Volumes inherit host ownership, so a non-root user may lack write access to a mounted path"", "Non-root users cannot read files", "It disables the healthcheck", "It prevents volume mounts"]",0,"This is why database images have an init step that fixes ownership of the data directory on first run. Understanding it prevents a class of confusing permission errors that only appear with volumes.",MEDIUM,storage
docker,"What is a practical reason to run a registry mirror without verifying its integrity?","[""There is not one; a mirror you do not control is a supply-chain risk"", "It removes the need for digests", "It speeds up pulls dramatically", "It signs images for you"]",0,"Verifying digests on pull means a mirror cannot silently change the bytes you receive. Skipping that check makes the mirror an untrusted source of your runtime.",MEDIUM,security
docker,"What does an image's entrypoint differ from its command?","[""The entrypoint is the executable run; the command supplies default arguments that can be overridden at run time"", "They are the same field with different names", "The command only applies to Windows containers", "The entrypoint is set at runtime only"]",0,"They compose: running a container executes entrypoint plus command. Overriding at run time replaces the arguments, which is why many images use a shell-form entrypoint that makes the command behave as intended.",MEDIUM,operations
docker,"When is a container image scan most useful in CI?","[""On every build, so a newly introduced vulnerability fails before it reaches a registry"", "Once a year during an audit", "Only before a production release", "Only for base images"]",0,"Scanning in CI shifts the feedback left from a production incident to a pull request. Gating on severity rather than any finding keeps it enforceable.",EASY,security
docker,"What is the practical benefit of tagging images with the commit SHA?","[""It makes the running version traceable to an exact source revision"", "It reduces image size", "It makes pulls faster", "It allows unsigned tags"]",0,"Traceability from a production pod back to a commit is worth a lot during an incident. Combining the SHA with a human-readable tag gives both.",EASY,deployment
docker,"Why can a container that works locally fail in CI?","[""Differences in kernel version, storage driver or architecture change what is available inside"", "Local machines have more memory", "CI uses a different shell", "Container behaviour differs on CI runners"]",0,"Architecture mismatch and storage-driver differences are the usual causes. Building and testing on the same target platform as production removes the entire class of problem.",MEDIUM,operations
docker,"What does an init flag do beyond zombie reaping?","[""It runs the application as a child of PID 1, so signal handling and exit codes work as expected"", "It speeds up the build", "It enables rootless mode", "It reduces memory usage"]",0,"Running as PID 1 breaks default signal handling and can leave zombies. An init process restores both, which matters most for graceful shutdown on deploy.",EASY,operations
docker,"Why is a JSON log file with no size limit a common cause of node failure?","[""It consumes the host disk, which starves every other service on that node"", "It slows the JSON parser", "It invalidates the image cache", "It prevents healthchecks"]",0,"This is a node-level incident caused by one container, and it is entirely preventable with log rotation. Worth configuring at the platform level rather than per service.",MEDIUM,operations
docker,"How do you pass a configuration file to a container without rebuilding the image?","[""Mount it as a volume or generate it from a config map, so the image stays environment-agnostic"", "Rebuild the image per environment", "Set it in a Dockerfile build argument", "Embed it in a layer label"]",0,"Keeping configuration outside the image is what allows one artefact to be promoted through every environment unchanged, which is the foundation of reproducible deployments.",MEDIUM,deployment
docker,"What is the trade-off of rootless container mode?","[""Better isolation from the host daemon, at the cost of some networking features and UID mapping complexity"", "It requires privileged containers", "It only works in development", "It improves performance"]",0,"Rootless mode reduces the blast radius of a daemon compromise considerably. The cost is losing some user-namespace networking features and dealing with subordinate UID ranges, so it is a deliberate operational choice.",MEDIUM,security
docker,"When should you choose a virtual machine over a container?","[""When you need a different kernel, full kernel isolation, or nested virtualisation"", "Always, for better performance", "Never, containers are strictly better", "Only on developer laptops"]",0,"Isolation strength is the deciding factor. Where a shared-kernel boundary is unacceptable, the extra overhead of a VM is the price of a genuinely separate kernel.",EASY,concepts
docker,"What is a common cause of a container image that is unexpectedly large despite a slim base?","[""Application logs and cache directories written into a later layer"", "A large base image", "Too many CPU limits", "A missing healthcheck"]",0,"Runtime caches and logs written during the build end up in whatever layer wrote them. Writing them to a declared volume instead of the filesystem keeps them out of the artefact.",EASY,builds
docker,"How do you verify that a running container matches the image you intended to deploy?","[""Compare the image digest from the runtime against the digest recorded at build time"", "Check the image tag", "Compare the container start time", "Review the entrypoint"]",0,"The tag is mutable and therefore proves nothing. The digest reported by the runtime is the only reliable identifier of the bytes actually running.",MEDIUM,deployment
docker,"What is the consequence of putting a secret in an image layer?","[""It persists in every pushed copy of that layer, even if a later layer deletes the file"", "It is deleted by the build", "Docker automatically redacts it", "It is encrypted in transit"]",0,"Layer deletion does not remove bytes, and registries retain history. The only reliable remediation is rotating the credential, which is why prevention matters more than cleanup.",MEDIUM,security
docker,"What makes a container's healthcheck worth having in production?","[""It turns application state into a signal that orchestration and alerting can act on automatically"", "It speeds up the container", "It reduces memory usage", "It enables load balancing"]",0,"Without it, orchestration sees a running process and assumes health. A healthcheck is what lets the platform restart or remove a container that is running but failing.",EASY,operations
docker,"What is the practical difference between a single run command and a compose file for one service?","[""Compose adds declarative configuration, networking and dependency definition from a version-controlled file"", "The run command cannot set environment variables", "Compose cannot build images", "The run command does not create networks"]",0,"For a single service the difference is mostly authoring style. Compose earns its place with several interdependent services, where the file becomes the shared source of truth.",EASY,operations
docker,"Why is it risky to assume a container's ephemeral storage is enough for a database?","[""The writable layer lives on the host disk, is not backed up, and is lost when the container is replaced"", "It is encrypted", "It is slower than a volume", "It cannot be written to"]",0,"Databases need durability and backup, both of which ephemeral storage cannot provide. Running one this way risks data loss on redeploy.",EASY,storage
docker,"What is the purpose of a resource reservation as well as a limit?","[""The reservation guarantees a minimum share, protecting against starvation by neighbours"", "The reservation replaces the limit", "Reservations only apply to CPU", "Reservations disable autoscaling"]",0,"Limits prevent one workload taking too much; reservations protect against a noisy neighbour on a shared node. Setting both gives predictable behaviour.",MEDIUM,operations
docker,"How should you handle a container image that no longer receives upstream updates?","[""Pin to a digest, mirror it internally, and plan a migration or rebuild"", "Keep pulling latest in the hope it updates", "Increase the pull frequency", "Disable vulnerability scanning"]",0,"Unmaintained images accumulate vulnerabilities with no path to a fix. Pinning and mirroring buys time, but only a rebuild or migration resolves it properly.",MEDIUM,security
docker,"What is the effect of a read-only root filesystem alongside tmpfs mounts?","[""The container can write only to explicitly mounted temporary paths, which suits stateless services"", "The container cannot start", "Logging stops working", "Networking is disabled"]",0,"Read-only plus tmpfs is a good default for stateless services: it makes persistence bugs impossible rather than merely unlikely, and tmpfs keeps ephemeral writes fast.",MEDIUM,security
docker,"When should you use a registry mirror rather than pulling from the public registry directly?","[""In CI or on a metered connection, to reduce repeated large pulls and avoid rate limits"", "Only for private images", "Never", "Only for production"]",0,"Public registry rate limits are per IP, which makes shared CI runners a common source of intermittent build failures. A mirror removes both the rate limit and the latency.",MEDIUM,operations
docker,"What does a multi-platform manifest allow you to do with a single tag?","[""Serve the correct image for amd64, arm64 and other architectures automatically"", "Combine several images into one layer", "Sign one image for many platforms", "Reduce the image size"]",0,"It is what makes a single tag usable across a mixed-fleet cluster. When you need an exact build, reference the digest rather than the tag.",EASY,operations
docker,"Why can a container that binds to loopback appear unreachable from the host even with a published port?","[""The port publish forwards to the container's interfaces, and a service bound to its loopback is not reachable there"", "Port publishing does not work", "The network is misconfigured", "The container has no IP address"]",0,"The fix is binding to all interfaces inside the container. It is a common first-run failure because the service works when run directly on the host.",EASY,networking
docker,"What is the security implication of running all containers in one root daemon?","[""A single container escape can compromise the daemon and every container it manages"", "Nothing", "Only performance is affected", "It prevents volume mounts"]",0,"Rootless mode or a separate daemon per trust boundary limits the blast radius. This is why multi-tenant platforms generally avoid sharing one root daemon across untrusted workloads.",MEDIUM,security
docker,"What is the advantage of an explicit compose file over ad-hoc run commands?","[""The configuration is version-controlled and reviewable, so environments are reproducible"", "It runs faster", "It uses less memory", "It builds images automatically"]",0,"A committed compose file is the source of truth for how a service runs, which makes review, rollback and environment parity possible. Ad-hoc commands capture none of that.",EASY,operations
docker,"Why should a Dockerfile pin base image digests in CI-built applications?","[""A moving tag means two builds of the same commit can produce different images"", "Tags are not supported in CI", "Digests reduce image size", "Digests disable caching"]",0,"Digest pinning is what makes a build reproducible and a rollback dependable. Updating the digest becomes a deliberate, reviewable action rather than an accident.",MEDIUM,builds
docker,"What is the practical downside of a very small pause between starting dependent services?","[""Services may start before dependencies are accepting traffic, producing intermittent failures"", "They start too slowly", "They use more memory", "Nothing"]",0,"A fixed sleep is not a readiness check. A conditional dependency, or an orchestrator readiness probe, waits for the actual capability rather than an interval.",MEDIUM,operations
docker,"When is it appropriate for two containers to share a single volume?","[""When they are components of one tightly coupled unit that share the same lifecycle and owner"", "Always, for performance", "Never", "Only for logging"]",0,"Shared volumes couple cleanup and permissions. Separate containers that happen to run on the same node should talk over the network, not a disk, unless they are genuinely one unit.",MEDIUM,storage
docker,"What does a container's exposed port mean in terms of security?","[""Nothing by itself; ports are reachable only if published or shared through a network the container joins"", "It opens a hole in the host firewall", "It requires root", "It exposes the host filesystem"]",0,"EXPOSE is metadata. The actual exposure comes from port publishing or network attachment, which is why two containers on the same user-defined bridge can reach each other without any published port.",EASY,networking
docker,"Why can a container image scan pass while the running host is still vulnerable?","[""The scan covers image packages, not the host kernel or runtime"", "Scans are always wrong", "The host cannot be scanned", "It has no effect"]",0,"Image scanning sees what you shipped. Host kernel and daemon vulnerabilities need separate scanning, so both are needed for a complete picture.",MEDIUM,security
docker,"What is the effect of using a build cache from an untrusted registry?","[""A malicious cache layer could alter build output without changing the Dockerfile"", "Nothing", "It only affects speed", "It is not possible"]",0,"Caching is a supply-chain boundary. Pinning and verifying the base image, and controlling cache provenance, prevents a poisoned cache from influencing your build.",MEDIUM,security
docker,"How should you handle a container whose entrypoint script is not executable?","[""Set it explicitly in the entrypoint or make it executable in a build step, rather than relying on host permissions"", "It runs with a warning", "Docker fixes the permission", "It only affects interactive shells"]",0,"Permission problems that would be obvious on a host are easy to introduce in an image because ownership and mode bits come from the build context. Setting them explicitly removes the ambiguity.",EASY,builds
docker,"What does a graceful shutdown signal handler need to do in a container?","[""Stop accepting new work, finish in-flight requests, then exit so the orchestrator's timeout is not exceeded"", "Exit immediately", "Ignore the signal", "Restart the process"]",0,"Orchestrators send SIGTERM then SIGKILL after a grace period. Handling SIGTERM properly is what avoids dropped requests and incomplete transactions on every deploy.",MEDIUM,operations
docker,"Which practice best prevents image-layer bloat from package installation?","[""Combine install and cleanup in a single run instruction, or use a multi-stage build"", "Run a cleanup command in a later layer", "Use a smaller base image only", "Add a .dockerignore"]",0,"Cleanup in a later instruction cannot remove bytes from the earlier layer. Doing it in one instruction, or building in a stage that gets discarded, is what actually shrinks the result.",EASY,builds
docker,"What is the value of declaring a healthcheck in a Dockerfile for a locally built image?","[""Compose and local tooling can honour it for dependency ordering and status reporting"", "It restarts the container automatically", "It reduces memory usage", "It speeds startup"]",0,"Docker itself only reports status. The value shows up in Compose and other tooling that can wait on or route around an unhealthy container.",MEDIUM,operations
docker,"How does a container's CPU quota interact with a multi-core workload?","[""Multiple replicas or a wider quota are usually needed, since quota is expressed in CPU periods rather than per-core behaviour"", "Quotas are ignored on multi-core", "Quotas only apply to single-threaded work", "It has no effect"]",0,"CPU quota and shares are easy to confuse. Quota enforces a ceiling regardless of core count, while shares distribute contention, and neither expresses parallelism on its own.",HARD,operations
docker,"What is a practical reason to run a service with a read-only filesystem and tmpfs for temporary files?","[""It removes persistence-based attack paths and catches bugs where state should not persist"", "It speeds up the service", "It allows root access", "It reduces image size"]",0,"Making accidental persistence impossible turns a silent correctness bug into an immediate failure, which is exactly what you want caught in staging rather than production.",MEDIUM,security
docker,"Why can a container's DNS resolution behave differently from the host?","[""The container uses the daemon's embedded resolver, which can differ in search domains and behaviour from the host's"", "DNS does not work in containers", "It requires host networking", "It only affects IPv6"]",0,"The embedded DNS on user-defined networks is usually what you want, but it does change resolution semantics. When DNS behaves oddly, comparing inside the container versus the host is a fast diagnostic.",MEDIUM,networking
docker,"What is the trade-off of using an init process such as tini as PID 1?","[""It fixes zombie reaping and signal handling at the cost of one more process to understand"", "It disables healthchecks", "It requires privileged mode", "It prevents scaling"]",0,"Correct PID 1 behaviour is genuinely subtle and easy to get wrong by hand. An init process is a small, well-understood dependency that removes a whole class of shutdown bugs.",EASY,operations
docker,"When should a Dockerfile run as a specific numeric UID rather than relying on a named user?","[""When the UID must be stable across rebuilds, because named users can resolve to different UIDs in different base images"", "Never", "Only for Windows images", "Only in development"]",0,"Fixing a numeric UID keeps file ownership consistent on mounted volumes and makes the image behave the same when the base image changes.",MEDIUM,security
docker,"What is the practical reason to separate build and run dependencies in a requirements file?","[""It lets the runtime stage omit compilers and headers, shrinking the image and reducing its attack surface"", "It speeds up Python only", "It is required by pip", "It enables caching"]",0,"Multi-stage builds need to know which dependencies are compile-time only. Without that split, the runtime image carries the entire toolchain.",MEDIUM,builds
docker,"What does an image's OOM score adjustment do?","[""It biases which process the kernel kills first when memory is exhausted, so the less important one dies instead"", "It reserves memory for the container", "It sets the memory limit", "It logs memory usage"]",0,"On a shared node, tuning OOM scores lets you protect critical processes from being killed in favour of disposable ones, turning a node-wide outage into one container restarting.",MEDIUM,operations
docker,"Why is it a problem to run a database in a container without resource limits?","[""It can consume the entire node and starve every other workload, so limits bound the blast radius"", "Databases ignore limits", "It slows the database", "It disables storage"]",0,"A limit does not make the database faster, but it converts a node-wide failure into one container restarting. That is the difference between an outage and a blip.",EASY,operations
docker,"What is the practical advantage of tagging an image with both a commit SHA and a semantic version?","[""The SHA gives traceability to source and the version gives something operators can read and request"", "It makes the image smaller", "It enables automatic signing", "It speeds up pulls"]",0,"The two answer different questions: what exactly is this, and what is it called. During an incident you often need both.",EASY,deployment
docker,"What happens if a container's restart policy is set to no and its process crashes?","[""It stays stopped until something explicitly starts it again"", "Docker restarts it once", "The node restarts", "It becomes unhealthy but keeps running"]",0,"No restart policy is a valid choice for jobs and one-off tasks. For a service it means a crash silently removes capacity until someone or something intervenes.",EASY,operations
docker,"When is a compose override file genuinely useful rather than confusing?","[""When local-only differences are kept in a separate file so the base definition stays shared"", "Never", "Only for production", "Only for secrets"]",0,"An override file is helpful when the difference is environmental and understood. It becomes a liability when required configuration lives only there, because the base file alone is no longer runnable.",MEDIUM,operations
docker,"What is the practical risk of passing many configuration values as environment variables?","[""Values are visible in the process environment and in image metadata, so secrets should not be passed this way"", "It slows startup", "It disables networking", "It has no effect"]",0,"Environment variables are readable from the container's process environment and are recorded in image history when used as build args. Mounted secret files avoid both.",MEDIUM,security
docker,"How should you verify that a container image has not been tampered with?","[""Verify its signature or digest against a trusted source before deploying"", "Check its size", "Check its creation date", "Run it and see if it works"]",0,"Running it successfully proves only that it functions, not that it is the artefact you reviewed. Signature and digest verification is what establishes provenance.",MEDIUM,security
docker,"What is the practical downside of a very long termination grace period?","[""A genuinely hung container stays in the draining state and delays rollout"", "It has no downside", "It increases image size", "It disables the healthcheck"]",0,"The grace period should be no longer than the slowest realistic shutdown. Excessive values slow deploys and can hold up a rollout that is already failing.",MEDIUM,operations
docker,"When does a healthcheck interval that is too short cause problems?","[""It adds load to both the service and the metrics pipeline, and can itself trigger the failures it detects"", "It has no effect", "It prevents restarts", "It slows the image"]",0,"Very frequent checks can be self-inflicted denial of service on a service already under stress. Choose an interval proportional to how quickly you need to know.",MEDIUM,operations
docker,"What is the practical benefit of running the same image in development and production?","[""It removes a class of environment-specific bugs and lets you trust that what you tested is what ships"", "It reduces image size", "It speeds up deployments", "It enables blue/green"]",0,"Environment parity is the practical payoff: the build that passed your tests is the artefact that reaches users, with no surprise differences in libraries or configuration.",MEDIUM,deployment
docker,"Why should a Dockerfile avoid running package updates as part of an install command?","[""It makes the build non-reproducible, since the result depends on when it ran"", "It is slower", "It requires root", "It prevents caching"]",0,"Pinning versions keeps builds reproducible and makes a regression traceable to a specific change. Updating deliberately, in its own reviewed step, keeps the change visible.",MEDIUM,builds
docker,"What is the risk of mounting a config file into a running container without restarting it?","[""Many services read config only at startup, so the change silently has no effect"", "The container crashes immediately", "It increases memory usage", "It invalidates the image"]",0,"Configuration reload without restart is application-specific and often unsupported. Assuming a live config change took effect is a common source of debugging confusion during incidents.",MEDIUM,operations
docker,"When should you use an init container in Kubernetes rather than a sidecar?","[""For one-time setup that must complete before the main containers start, such as generating config or running migrations"", "For continuous background work", "Never", "Only in development"]",0,"An init container runs to completion before the main containers start, which is what makes it correct for setup. A sidecar is for work that must run alongside and for the pod's lifetime.",MEDIUM,operations
docker,"What is the main operational risk of running many containers on a node without resource limits?","[""One misbehaving container can exhaust shared node resources and take down every co-located workload"", "Containers cannot share a node", "It slows image pulls", "It prevents logging"]",0,"Node-level isolation without limits is only nominal. Limits and reservations make the sharing explicit, so a single bad container degrades itself rather than the whole node.",MEDIUM,operations
docker,"Why does running an application in a container not remove the need for host-level security?","[""The kernel is shared, so a kernel or daemon vulnerability still reaches every container on the host"", "Containers have their own kernel", "Host security is unnecessary in the cloud", "Containers disable MAC labelling"]",0,"Isolation reduces what one workload can reach, but it does not create a separate kernel. Host patching, access control and runtime security remain the foundation containers build on.",EASY,security
docker,"What is the practical advantage of keeping a container's log format structured?","[""Fields can be queried and filtered without fragile text parsing, which matters at volume"", "It reduces disk usage", "It speeds up the application", "It enables compression"]",0,"At high volume, unstructured logs force either expensive full-text scanning or lossy sampling. Structured fields let you keep everything and still query it precisely.",MEDIUM,operations
docker,"When should a Dockerfile use a non-root user together with a writable volume?","[""When the service needs to persist state but the root filesystem should stay read-only"", "Never", "Only for databases", "Only in development"]",0,"The combination is the standard shape for stateful services: state goes to a volume with explicit ownership, and the image filesystem stays immutable and non-root.",MEDIUM,operations
docker,"What is the practical downside of exposing a container's debug port to a shared network?","[""Anyone on that network can reach it and inspect or alter process state, which is a serious exposure"", "It uses more CPU", "It disables the healthcheck", "It slows networking"]",0,"Debug ports should be reachable only from an operator's machine via port-forwarding, never as a generally reachable service. Exposing one is a common and easily missed vulnerability.",MEDIUM,security
docker,"What is the practical risk of running an image whose layers were built by different people?","[""Trusting one layer means trusting the whole chain, so provenance matters as much as the final image"", "It increases image size", "It slows pulls", "It disables caching"]",0,"Each layer is content-addressed and immutable, which is good for integrity, but it means the build history and who produced each layer are part of what you are trusting.",MEDIUM,security
docker,"When should a container's CPU and memory limits be revisited?","[""When observed usage shows the limit is consistently far from actual need in either direction"", "Never after deployment", "Only after an outage", "Only in development"]",0,"Setting limits from a guess either wastes capacity or causes throttling and OOM kills. Observing real usage first turns this into a tuning exercise rather than a guessing one.",MEDIUM,operations
docker,"What is the practical consequence of an image that ships its own bundled runtime alongside the base?","[""It can conflict with the base's libraries and doubles the attack surface"", "It speeds up startup", "It reduces CPU usage", "It prevents volume mounts"]",0,"Bundled runtimes are a common source of subtle version conflicts. Prefer the base image's runtime, or use a distroless image that supplies exactly one known version.",MEDIUM,builds
docker,"Why should a service that handles secrets prefer a mounted secret file over an environment variable?","[""It avoids leaking the value through process listings and image metadata, and rotation does not require a restart"", "Files are always faster", "Environment variables cannot hold secrets", "Files are encrypted automatically"]",0,"The practical advantage is rotation and reduced exposure: the file can be updated by the secret manager without restarting, and the value is not in the process environment that diagnostics frequently print.",MEDIUM,security
docker,"What is the practical value of labelling every image with its source revision?","[""It lets you trace a running container back to the exact commit and its review history"", "It speeds up deployment", "It reduces image size", "It enables encryption"]",0,"During an incident the first question is usually which change is running. Recording the revision makes that answerable without archaeology.",EASY,operations
docker,"When should you prefer explicit, minimal permissions to broad ones even inside a container?","[""Because a container escape or a compromised process gains only what it was granted"", "It has no effect inside a container", "It slows startup", "It reduces image size"]",0,"Containers reduce what an attacker can reach, but least privilege is what limits how far they get once inside. The two defences are complementary, not substitutes.",EASY,security
docker,"What is the practical value of a healthcheck that does not depend on external dependencies?","[""It distinguishes the service being broken from a dependency being unavailable"", "It reduces cost", "It speeds up deployments", "It disables restarts"]",0,"If liveness depends on a database, a database blip restarts every replica simultaneously. Keeping liveness shallow and putting dependency checks in readiness avoids that cascade.",MEDIUM,operations
docker,"What is the practical consequence of caching a build layer that includes a test run?","[""Test results are baked into the image and are not re-run when the code changes"", "It slows the build", "It prevents caching", "It enlarges the image"]",0,"Including test output in a cached layer means a code change reuses the previous test result. Tests belong in CI, not in the image that ships.",MEDIUM,builds
docker,"Why is a fixed image tag for an internal service still worth avoiding?","[""It makes rollback unreliable, since the tag may have moved since you last verified it"", "Internal services cannot use tags", "It is slower to pull", "It prevents scaling"]",0,"The same reasoning applies regardless of who consumes the service. When you need to roll back, you need to name the bytes, not the label.",MEDIUM,operations
docker,"What is the practical risk of running a container whose filesystem has been modified since it started?","[""The running state cannot be reproduced from its image, so incidents cannot be reconstructed from the artefact"", "It uses more disk", "It disables the healthcheck", "It prevents logging"]",0,"Immutable containers are what let you treat a running system as describable by an image plus configuration. Drift breaks that guarantee silently.",MEDIUM,operations
docker,"When should you add an entrypoint script that validates required configuration?","[""At startup, so a misconfigured deployment fails immediately rather than at first request"", "Never", "Only in development", "Only for scheduled jobs"]",0,"Fail-fast startup turns a silent partial failure into an immediate, obvious one. It is much cheaper to diagnose than a service that starts healthy and fails under real traffic.",EASY,operations
docker,"What is the practical benefit of tagging images with the build timestamp?","[""It helps establish the order in which artefacts were produced when investigating an incident"", "It improves caching", "It reduces size", "It signs the image"]",0,"Timestamp metadata is cheap and helps order events when several images from the same source are in play. The commit SHA remains the authoritative identifier.",MEDIUM,operations
docker,"When should a container's image be rebuilt even though no source changed?","[""When a base image or dependency has a fix that matters, and rebuilding is how you adopt it"", "Never", "Only on a schedule regardless", "Only after an incident"]",0,"Adopting upstream fixes requires a rebuild, which is why the base digest should be tracked as a deliberate update rather than a surprise. Cadence should follow the severity of what you are exposed to.",EASY,operations
docker,"What is the practical downside of an image with a very long history of many small layers?","[""More layers mean more metadata overhead and slower pulls, even though content deduplication keeps the size reasonable"", "It increases the attack surface", "It prevents caching", "It enlarges the image"]",0,"Splitting sensible steps into many tiny instructions is counterproductive. Group related work into one instruction and rely on ordering for cache efficiency instead.",MEDIUM,builds
docker,"Why should you avoid running a container that mounts the host's kernel interfaces?","[""These expose kernel internals and process state to the container, weakening isolation significantly"", "They make the container faster", "They are required for logging", "They disable networking"]",0,"Host kernel interfaces mounted into a container are a well-known escalation path. Where a workload genuinely needs them, it should be treated as having host-level privilege.",MEDIUM,security
docker,"What is the practical advantage of running a service's cache in the same container as the service?","[""It is fast and simple, and appropriate when losing the cache is acceptable"", "It is always better than an external cache", "It improves durability", "It removes memory limits"]",0,"Co-locating the cache is a legitimate choice for a disposable cache where a cold start is cheap. It stops being appropriate as soon as the cache must survive restarts or be shared.",MEDIUM,design
docker,"When should you verify that a container's declared port matches what the process actually binds?","[""In smoke tests, because a mismatch produces a container that starts but is never reachable"", "Never", "Only in production", "Only for Node services"]",0,"The failure is silent from the platform's perspective: the process runs, the healthcheck on the wrong path fails, and the cause is not obvious. A smoke test that actually calls the declared port catches it.",MEDIUM,operations
docker,"What is the practical value of recording which registry an image came from?","[""It tells you whether a digest is from a source you trust or from a mirror someone else controls"", "It speeds up pulls", "It reduces size", "It enables encryption"]",0,"A mirror you control and one you do not are different trust domains. Provenance is what tells you which one served the bytes.",MEDIUM,security
docker,"Why should a production container avoid running with a tty allocated?","[""It changes signal and buffering behaviour, and a service can hang waiting for input that never arrives"", "It slows the container", "It is required by Docker", "It disables healthchecks"]",0,"Without a tty, applications see stdin closed and their buffering behaves correctly. This is why exec-form entrypoints exist: a shell-form entrypoint runs as PID 1 and mishandles signals.",MEDIUM,operations
docker,"What is the practical consequence of a service that writes large files to its own filesystem by default?","[""It fills the container's writable layer, which is unbounded and shared with the node's disk"", "Nothing", "It disables logging", "It prevents scaling"]",0,"Any unbounded write to the writable layer is a disk exhaustion risk. Declaring volumes and setting a read-only root filesystem turns that into an immediate, visible error.",MEDIUM,operations
docker,"What is the practical risk of a Dockerfile that uses ADD with a URL?","[""The image contents depend on network state at build time, so the same Dockerfile can produce different images"", "ADD is slower", "It disables caching", "It requires root"]",0,"A URL fetch makes builds non-reproducible and fails unpredictably. Fetch in a separate, verified step and copy the artefact in, so the build input is pinned.",MEDIUM,builds
docker,"Why should you prefer copying a verified checksum file alongside a dependency in a build?","[""It proves the artefact matches what you reviewed rather than trusting the download host"", "It speeds up the build", "It reduces image size", "It enables caching"]",0,"Checksum verification is how supply-chain integrity is established at build time. Without it you are trusting whatever the server returned.",MEDIUM,security
docker,"What is the practical benefit of keeping a container's process count minimal?","[""Fewer processes means less to monitor, less shared memory overhead, and clearer signal handling"", "It reduces image size", "It disables healthchecks", "It prevents scaling"]",0,"Extra processes inside a container complicate debugging, memory accounting and shutdown, and often come from a shell wrapper that could be replaced with exec form.",EASY,operations
docker,"When should you review and update a container's pinned dependencies deliberately?","[""On a defined cadence, and sooner when a fix for something you are exposed to is released"", "Never", "Only after an incident", "Whenever a build fails"]",0,"Deliberate cadence means you adopt fixes on your terms with testing, rather than urgently mid-incident when every change is riskier.",MEDIUM,operations
docker,"What is the practical consequence of running an application that assumes a writable root filesystem?","[""It fails immediately when deployed with a read-only root filesystem, rather than degrading safely"", "It uses more memory", "It cannot reach the network", "It disables logging"]",0,"Testing with a read-only root filesystem surfaces accidental writes before they become a production incident. It is a cheap check with a clear failure mode.",MEDIUM,operations
docker,"Why should image builds avoid depending on the current date or hostname?","[""It makes output differ between builds for no reason, defeating reproducibility"", "It is slower", "It requires root", "It disables caching"]",0,"Timestamps, random values and machine names embedded at build time are the usual culprits. Fix them so the same source produces the same bytes.",MEDIUM,builds
docker,"What is the practical value of testing that a container starts correctly with no network access?","[""It proves dependencies are properly declared rather than silently assumed"", "It speeds up startup", "It reduces memory usage", "It disables healthchecks"]",0,"A service that only starts when it can reach something at boot is hiding an undeclared dependency. Starting in isolation makes that visible immediately.",MEDIUM,operations
docker,"When should you use a container image's declared entrypoint as a process supervisor?","[""When you need a real supervisor such as s6 or dumb-init to run several processes in one container"", "Never", "Always", "Only in Kubernetes"]",0,"Running multiple long-lived processes is generally discouraged in favour of separate containers, but when it is necessary, a real supervisor is what handles signals and reaping correctly.",MEDIUM,operations
docker,"What is the practical risk of a container image whose base is maintained by an individual rather than an organisation?","[""Maintenance may stop without notice, leaving you on an unpatched dependency with no upgrade path"", "Individual images are always faster", "It prevents caching", "It slows pulls"]",0,"Popularity is a weak proxy for maintenance. Check whether the base has a security contact, a release cadence and a history of responding to vulnerabilities before depending on it.",MEDIUM,security
docker,"Why should you treat a container's exposed ports as an API surface?","[""Each one is a reachable entry point that needs authentication, rate limiting and monitoring"", "Ports cannot be secured", "It slows down networking", "It reduces image size"]",0,"Publishing a port makes it reachable and therefore part of your attack surface. It deserves the same scrutiny as a public API endpoint, including the decision not to expose it at all.",MEDIUM,security
docker,"What is the practical benefit of a service declaring its resource requests as well as limits?","[""Requests let the scheduler place it sensibly, so limits become a guardrail rather than a surprise"", "It removes the need for limits", "It speeds up the service", "It disables autoscaling"]",0,"Without requests, the scheduler is guessing at placement, and autoscaling metrics derived from limits can be meaningless. Requests are what make limits meaningful.",MEDIUM,operations
docker,"When should you rebuild a container rather than patching a running container in place?","[""Almost always: patching breaks reproducibility, so rebuild and redeploy from a known artefact"", "During an incident, to save time", "Never", "Only for one-off tools"]",0,"Hot-patching a container leaves the running system undescribable by any artefact, which is precisely when you need that description most. Rebuilding takes minutes and preserves your ability to reason about state.",MEDIUM,operations
docker,"What is the practical consequence of an image built with a shell wrapper that does not exec the final command?","[""The application runs as a child of the shell, so it never receives signals and the container cannot shut down cleanly"", "It slows startup", "It uses more memory", "It disables healthchecks"]",0,"This is why exec-form entrypoints exist. Without exec, the termination signal goes to the shell, which does not forward it, and the orchestrator eventually kills the container mid-request.",EASY,operations
docker,"What is the practical value of testing a container's behaviour when its dependency is slow rather than down?","[""Slow dependencies often cause cascading failures that a simple down test misses"", "It is unnecessary", "Only for databases", "It only tests the network"]",0,"Timeouts and retries designed for outright failure can behave badly under latency, producing retry storms. Testing the slow path is how you find that before production does.",MEDIUM,operations
docker,"Why should you document why a container image exists and what owns it?","[""Ownership determines who patches it, responds to alerts and approves updates when it breaks"", "It speeds up builds", "It reduces image size", "It enables scaling"]",0,"Unowned images are the ones that stay vulnerable. Recording the owning team and the reason it exists is what makes it clear who acts when a finding appears.",EASY,operations
docker,"What is the practical risk of running many similar container images with slightly different base versions?","[""Patch levels diverge so a fix must be applied and verified several times, and version comparisons get confusing"", "It uses more CPU", "It prevents caching", "It slows image pulls"]",0,"Consolidating onto fewer base lines makes security updates tractable. A fleet of near-duplicate images turns one upstream fix into a dozen separate projects.",MEDIUM,operations
docker,"When should a container's healthcheck use a dedicated lightweight endpoint?","[""When the main path is expensive or has side effects, so probing does not add load or change behaviour"", "Never", "Always", "Only in production"]",0,"The check runs repeatedly, so it has to be cheap and free of side effects. A readiness endpoint that validates configuration is usually the right compromise.",MEDIUM,operations
docker,"What is the practical benefit of recording the base image digest in your own release metadata?","[""It lets you determine later exactly which upstream version a deployed artefact incorporated"", "It speeds up pulls", "It reduces image size", "It enables caching"]",0,"When a vulnerability is announced against a base version, this record answers whether you are affected without having to reconstruct the build.",MEDIUM,operations
docker,"Why should you avoid running a container that can reach the cloud metadata service unrestricted?","[""It can be a route to instance credentials, so restricting access with a hop limit is a standard control"", "Metadata is always blocked", "It slows startup", "It prevents scaling"]",0,"The metadata service is a common target because instance credentials live behind it. Hop limits and session tokens reduce the risk of a server-side request forgery turning into credential theft.",MEDIUM,security
docker,"What is the practical consequence of a Dockerfile that installs packages without pinning versions?","[""Builds are non-reproducible and an upstream release can change behaviour without any change on your side"", "It installs fewer packages", "It speeds up the build", "It disables caching"]",0,"Pinning makes the build reproducible and turns an upstream change into a reviewed update rather than an incident discovered later.",MEDIUM,builds
docker,"When should you consider replacing a container entirely rather than upgrading it?","[""When it is unmaintained, has no security contact, or no longer fits the workload"", "Never", "Only on major version changes", "Only after a security incident"]",0,"Upgrading assumes a maintainer and a release path. Neither existing, the honest options are replacing the component or removing the dependency, neither of which is an upgrade.",MEDIUM,security
docker,"What is the practical value of a container image being small beyond deployment speed?","[""Fewer packages mean fewer vulnerabilities, less memory pressure and faster start-up"", "It only affects pull time", "It reduces CPU usage only", "It has no security benefit"]",0,"Size is a proxy for how much third-party code you are shipping and keeping patched. Reducing it reduces maintenance work and attack surface at the same time.",EASY,operations
docker,"Why should you run a container's healthcheck as the same user the application runs as?","[""A check that passes as root can mask missing permissions for the actual runtime user"", "It speeds up the check", "It is required by Docker", "It reduces memory use"]",0,"Health checks that run with more privilege than the service will not detect the permission problems that matter in production.",MEDIUM,operations
docker,"What is the practical risk of relying on a container's image tag for rollback after a failed release?","[""If the tag moved during the failed deployment, rolling back may redeploy the same bad artefact"", "Tags cannot roll back", "It slows the rollback", "It increases image size"]",0,"This is the practical reason deployments reference digests. With a tag, the artefact you roll back to is whatever the tag points at now, which may be the failure itself.",MEDIUM,deployment
docker,"When should you document the resource profile a container expects to run at?","[""So capacity limits and autoscaling thresholds are set from measured behaviour rather than assumption"", "Only in development", "Only for databases", "Never, it is discoverable"]",0,"Documented expected usage lets operators set limits sensibly and spot a regression that changes the profile, such as a memory leak.",EASY,operations
docker,"Why should you avoid a container image that vendors its dependencies into the repository?","[""Updates become manual and security patches are easy to miss"", "It makes builds faster", "It reduces image size", "It prevents caching"]",0,"Vendoring gives you reproducibility only at the cost of losing the upstream patch path. Most projects are better served by pinning and rebuilding on a deliberate cadence.",MEDIUM,security
docker,"What is the practical advantage of running a stateless service that can be replaced at any moment?","[""Deploys, scaling and recovery all become simple because there is no local state to preserve"", "It uses more memory", "It is faster", "It disables healthchecks"]",0,"Statelessness converts recovery from a restoration problem into a restart, which is why it is the default target even when something looks easier to keep stateful.",EASY,design
docker,"When should you verify an image's contents rather than trusting its documentation?","[""When you are assessing an unfamiliar or third-party image, before it handles real traffic or secrets"", "Never", "Only in production", "Only for public images"]",0,"Documentation describes intent; the filesystem describes reality. Checking what is actually installed is how you find surprises before they matter.",MEDIUM,security
docker,"Why is it important to know whether a container image ships as root by default?","[""It determines whether a deployment that omits a user directive silently runs privileged"", "It has no effect", "It only affects the build", "It changes the image size"]",0,"This is exactly the kind of detail that is easy to miss and significant in practice. Verify it rather than assuming a base image is safe by default.",EASY,security
docker,"What is the practical value of tagging an image with the toolchain version used to build it?","[""It helps explain a build difference when the same source produces different output on different builders"", "It speeds up builds", "It reduces size", "It enables caching"]",0,"Toolchain differences explain a class of puzzling build non-determinism. Recording it makes the difference visible instead of mysterious.",MEDIUM,builds
docker,"When should you do container's healthcheck use a readiness endpoint rather than the main path?","[""When the main path has side effects or is too expensive to call on every probe"", "Never", "Always", "Only in production"]",0,"Probes run constantly, so the endpoint has to be cheap and idempotent. Validating configuration or dependency reachability is the usual middle ground.",MEDIUM,operations
docker,"When should you treat an image vulnerability finding as not applicable?","[""When the vulnerable component is demonstrably absent from the shipped artefact or unreachable from untrusted input, and you can show why"", "Whenever it is inconvenient", "When the scan rate is low", "Never"]",0,"Suppressing a finding is reasonable when the reasoning is documented and verifiable. Suppressing because triage is expensive is how real exposure accumulates.",MEDIUM,security
docker,"What is the practical benefit of building an image once and promoting the same digest through environments?","[""It guarantees that what passed testing is what runs in production"", "It reduces storage cost", "It speeds up builds only", "It simplifies networking"]",0,"This is the central practice behind reliable delivery. Any step that rebuilds between environments reintroduces the possibility of shipping untested bytes.",MEDIUM,deployment
docker,"Why should you avoid relying on a container's default exposed port in documentation?","[""Because EXPOSE is metadata, and the actual reachability comes from publishing or network attachment"", "EXPOSE sets the port automatically", "It is required by Docker", "It enables networking"]",0,"Documentation implying exposure is a source of confusion about what is actually reachable. Describe the publishing explicitly instead.",MEDIUM,operations
docker,"What is the practical consequence of a service that opens a port it does not need?","[""It is an unnecessary reachable entry point, widening the attack surface for no benefit"", "It uses more memory", "It slows startup", "It has no effect"]",0,"Unnecessary listeners are easy to leave behind after a refactor and rarely noticed. Closing what is unused is one of the cheapest security improvements available.",MEDIUM,security
docker,"When should you add an explicit stop signal and grace period for a container?","[""For long-running services, so in-flight work completes instead of being cut off mid-request"", "Never", "Only in production", "Only for stateful services"]",0,"Deploys are frequent, so shutdown behaviour affects users many times a day. Handling termination properly is what prevents dropped requests and partial writes.",EASY,operations
docker,"What is the practical value of recording the container runtime version in deployment records?","[""It separates an application regression from a runtime change when behaviour shifts unexpectedly"", "It speeds up deployment", "It reduces image size", "It enables caching"]",0,"Runtime upgrades do change behaviour, particularly around networking and storage. Knowing the version turns a puzzling difference into a specific one.",MEDIUM,operations
docker,"When should you use a container image scanner as a required CI check rather than an advisory report?","[""Once the baseline is clean enough to gate on, so new findings cannot be introduced unnoticed"", "Never", "Only in production", "Only for critical services"]",0,"Gating works once existing findings are triaged and tracked; before that it is noise that gets ignored. Establish the baseline, then enforce no-new-findings.",MEDIUM,security
docker,"Why should a Dockerfile avoid leaving unnecessary package-manager state in an earlier layer?","[""Because it cannot be removed later, so the bytes persist even when hidden"", "It slows the build", "It is required by the package manager", "It prevents caching"]",0,"This is the single most common cause of unnecessary image size. Multi-stage builds or combined instructions are the reliable fix.",MEDIUM,builds
docker,"What is the practical benefit of pinning the OS base image and updating it on a schedule?","[""It gives you reproducibility now and a controlled path to security updates later"", "It eliminates the need for scanning", "It prevents caching", "It reduces CPU usage"]",0,"These are not in conflict: pin for determinism, then update deliberately with testing. Floating tags give you neither guarantee nor control.",EASY,builds
docker,"When should you confirm that a container's filesystem writes go to a declared volume?","[""Under test, because a write to the writable layer is lost on redeploy and may look like data loss in production"", "Never", "Only in production", "Only for databases"]",0,"This is a common and severe production failure that staging can reproduce in seconds by recreating the container. Testing the recreate path is what catches it.",MEDIUM,storage
docker,"What is the practical consequence of running a service that assumes its configuration is in a file it wrote itself?","[""It behaves differently on restart when the file is absent, so restarts silently change behaviour"", "It uses more memory", "It slows startup", "It disables healthchecks"]",0,"Configuration written at runtime and configuration declared at deploy are different things. Treating them as the same is a common source of restart-only failures.",MEDIUM,operations
docker,"When should you record a container's expected traffic pattern in its documentation?","[""So capacity limits and autoscaling thresholds are set from realistic assumptions"", "Only in production", "Never", "Only for databases"]",0,"Autoscaling thresholds derived from guesses produce either waste or outages. A documented expected pattern is what turns tuning into a reasoned adjustment.",MEDIUM,operations
docker,"Why should you avoid a container image whose entrypoint depends on a shell that may not exist in a minimal base?","[""The container starts and immediately fails, which is a confusing failure with a simple cause"", "It is faster", "It reduces size", "It enables caching"]",0,"Minimal bases intentionally have no shell. Either use a shell-based base deliberately or use exec form, so the intent is explicit rather than discovered at runtime.",EASY,operations
docker,"What is the practical benefit of scanning a container image for malware in CI?","[""It catches a compromised dependency or build step before the artefact reaches a registry"", "It reduces image size", "It speeds up builds", "It enables caching"]",0,"Vulnerability scanning asks whether known flaws are present; malware scanning asks whether something unexpected was introduced. They answer different questions and both are worth running.",MEDIUM,security
docker,"When should you document how to roll back a container deployment?","[""Before you need it, since rollback under pressure is exactly when you will not have time to work it out"", "After the first incident", "Only in production", "Never"]",0,"Rollback is a procedure, not an intuition. Knowing which artefact to return to and how takes minutes to write down and saves considerably more when something is broken.",EASY,deployment
docker,"Why should you ensure a container's time zone and locale are set explicitly?","[""Logs and scheduled behaviour become comparable across hosts and reproducible between environments"", "It speeds up the container", "It reduces memory usage", "It has no effect"]",0,"Implicit host defaults make logs harder to correlate and scheduling quietly environment-dependent. Explicit configuration removes a common source of production-only surprises.",EASY,operations
docker,"What is the practical consequence of an image that installs a package with a known unpatched vulnerability?","[""It introduces known exposure that a scan will keep reporting until it is removed or upgraded"", "It slows startup", "It increases size", "It has no effect"]",0,"This is why gating on new findings matters: each one shipped is a debt that recurs on every scan until someone deals with it.",MEDIUM,security
docker,"When should you use an init process for a container that runs a shell entrypoint?","[""Because a shell as PID 1 mishandles signals and reaping, which breaks graceful shutdown"", "Never", "Always", "Only in development"]",0,"The shell entrypoint pattern is common and quietly broken at shutdown. Either exec the final command or add an init process so termination works as expected.",EASY,operations
docker,"What is the practical value of a container image being independently rebuildable?","[""It lets you apply a fix or base update without waiting for or entangling other components"", "It reduces storage cost", "It speeds up builds", "It enables caching"]",0,"Independent rebuildability is what keeps a large estate manageable. Coupled images turn every change into a coordinated release across everything that depends on them.",MEDIUM,operations
docker,"Why should you avoid a Dockerfile that relies on the latest available package version by default?","[""It makes builds non-reproducible, so the same source can produce different output over time"", "It is slower", "It installs fewer packages", "It prevents caching"]",0,"Unpinned versions mean you cannot say what is running without checking the registry, and a build that worked yesterday may fail today for reasons unrelated to your code.",MEDIUM,builds
docker,"What should you verify after changing a container's base image?","[""That the service still starts, its healthcheck passes, and its behaviour under load is unchanged"", "Only that the build succeeded", "That the image is smaller", "That it pulled faster"]",0,"A base image change can alter libc, timezone data, TLS behaviour and default limits. Functional and load testing is what catches those; a successful build tells you nothing about runtime behaviour.",MEDIUM,operations
docker,"When is it reasonable to run a container with no resource limits at all?","[""In a short-lived local experiment, never for a service with neighbours on the node"", "Always", "Never, in any environment", "Only in production"]",0,"Being explicit about this: unbounded is acceptable when nothing else shares the machine and the process is short-lived. On a shared node it is a decision to let one workload risk everyone's.",MEDIUM,operations
docker,"What is the practical risk of relying on a container's default DNS in a multi-container network?","[""Services resolve by service name, so a naming change silently reroutes traffic without any code change"", "DNS does not work in containers", "It requires host networking", "It only affects IPv6"]",0,"Service-name resolution is convenient, and it also means a renamed service can redirect callers invisibly. Knowing which names resolve where makes that failure mode diagnosable.",MEDIUM,networking
docker,"Why should a production image end with a non-root user rather than relying on a run flag?","[""The image is correct by default, so nobody can accidentally start it as root"", "It speeds up the build", "It enables layer caching", "It is required by the registry"]",0,"Defence by default beats a flag everyone has to remember. A run flag can be omitted; a user instruction cannot.",EASY,security
docker,"What is the practical advantage of separating a long-running service from a one-off task in a deployment?","[""They have different lifecycles, so a completed job is not restarted and a crashing service is not silently retried"", "It reduces image size", "They cannot share a network", "It disables logging"]",0,"Choosing the right restart policy per workload type is what stops completed migrations looping forever and stops real crashes from being masked.",MEDIUM,operations
docker,"What is the practical consequence of caching a build layer that includes secret material?","[""The secret is recorded in image history and recoverable from the pushed image"", "It is encrypted at rest", "It has no effect", "It is removed by the build"]",0,"Build-time caching and build arguments are separate mechanisms, but both leave traces. Secret mounts exist precisely because neither is safe for credentials.",MEDIUM,security
docker,"What is the practical benefit of a container's image being reproducible byte for byte?","[""It lets you verify that what you tested is what you ship, and prove a deployed image came from audited source"", "It reduces storage cost", "It speeds up pulls", "It enables caching"]",0,"Reproducibility is what makes verification meaningful. Timestamps, ordering and floating tags all break it, and each break removes your ability to prove what is running.",MEDIUM,builds
docker,"What is the practical downside of a very small pause between starting dependent containers?","[""Services may start before dependencies are accepting traffic, producing intermittent first-boot failures"", "They start too slowly", "They use more memory", "Nothing"]",0,"A fixed sleep is not a readiness check. Waiting on an actual readiness signal removes an entire category of failures that only appear under load or in slower environments.",MEDIUM,operations
docker,"When should a container's declared port be considered part of its public API?","[""When it is published to an address other than loopback, since anyone who can route to it can call it"", "Always", "Never", "Only when it is documented"]",0,"Publishing to a non-loopback address makes the port reachable, which means it inherits all the obligations of a public endpoint: authentication, rate limiting and monitoring.",MEDIUM,networking
docker,"What is the practical risk of relying on a single registry for all your images?","[""A registry outage or compromise affects every deployment, with no independent fallback"", "It is slower", "It increases image size", "It prevents caching"]",0,"Registry concentration is a single point of failure and a single source of compromise. A mirror you control, with digests verified on pull, is the practical mitigation.",MEDIUM,security
docker,"What is the practical value of scanning for vulnerabilities as part of the build rather than on a schedule?","[""Findings arrive while the change that introduced them is still open and cheap to fix"", "It reduces scan cost", "It removes false positives", "It is faster"]",0,"Timing determines cost. A finding at build time is a small edit to a line the author just wrote; the same finding next quarter is an investigation into who changed what and why.",MEDIUM,security
docker,"What is the consequence of an image that cannot be rebuilt because its build script depends on an external service that has shut down?","[""A security fix to the base image becomes impossible to adopt, freezing the image on a vulnerable state"", "It has no effect", "Only the build times increase", "The image cannot be pulled"]",0,"This is a real and underappreciated form of lock-in: the build pipeline itself becomes a dependency you no longer control. Vendoring or pinning build-time inputs is what prevents it.",MEDIUM,security
docker,"When should you prefer a maintained upstream image over a self-built one for a standard runtime?","[""Usually, because it receives security updates from people who can see the whole ecosystem"", "Never", "Always", "Only for development"]",0,"Maintaining your own base means tracking vulnerabilities across every transitive dependency yourself. Rebuilt from source is justified when you need specific patches the upstream does not carry, or when licensing demands it.",MEDIUM,security
docker,"What is the practical downside of running a container without a defined owner?","[""Nobody is accountable for patching it or responding to an alert naming it"", "It runs slower", "It uses more memory", "It prevents scaling"]",0,"Ownership is the mechanism that turns a vulnerability finding into an action. An unowned image is one where nothing happens, and that risk accumulates silently with every scan.",EASY,operations`;
